(function(){"use strict";const r=document.querySelector(".cg");if(!r)return;const c=r.querySelector("[data-filters]");if(!c)return;c.hidden=!1;const n=[...c.querySelectorAll("button")],o=[...r.querySelectorAll(".cg-event")],a=[...r.querySelectorAll(".cg-year")];function s(t){n.forEach(e=>e.setAttribute("aria-pressed",String(e.dataset.type===t))),o.forEach(e=>{e.hidden=t!=="all"&&e.dataset.type!==t}),a.forEach(e=>{e.hidden=!e.querySelector(".cg-event:not([hidden])")})}n.forEach(t=>t.addEventListener("click",()=>s(t.dataset.type)))})();
